#[cfg(test)]
mod tests {
    use super::*;

    fn materials() -> Vec<Material> {
        crate::material::starter()
    }

    #[test]
    fn the_starter_types_check_and_have_names_of_their_own() {
        let types = starter();
        assert_eq!(types.len(), 30);
        for t in &types {
            t.check(&materials()).unwrap_or_else(|e| panic!("{}: {e}", t.id));
            // a floor or a ceiling lies, the others stand
            assert_eq!(t.lying.is_some(), t.group.lies(), "{}", t.id);
        }
        for lang in Lang::ALL {
            let mut names: Vec<String> = types.iter().map(|t| t.rule_name(&materials(), lang)).collect();
            names.sort();
            names.dedup();
            assert_eq!(names.len(), types.len(), "{lang:?}: {names:?}");
        }
    }

    #[test]
    fn a_type_is_named_after_its_members_or_its_panels() {
        let types = starter();
        let name = |id: &str, lang| types.iter().find(|t| t.id == id).unwrap().rule_name(&materials(), lang);
        assert_eq!(name("system.curtain-wall-aluminium-1500", Lang::Nl), "Vliesgevel aluminium 50×150 h.o.h. 1500");
        assert_eq!(name("system.curtain-wall-aluminium-1500", Lang::En), "Curtain wall aluminium 50×150 c/c 1500");
        // the group's name says the material
        assert_eq!(name("system.timber-frame-140", Lang::Nl), "Houtskeletbouw 38×140 h.o.h. 600");
        assert_eq!(name("system.timber-frame-140", Lang::Fr), "Ossature bois 38×140 entraxe 600");
        assert_eq!(name("system.timber-frame-235-610", Lang::En), "Timber frame 38×235 c/c 610");
        assert_eq!(name("system.timber-frame-internal-89", Lang::Nl), "Houtskeletbouw 38×89 h.o.h. 600");
        assert_eq!(name("system.frame-pvc-70", Lang::De), "Rahmen PVC 64×70 Achsabstand 1000");
        assert_eq!(name("system.masonry-waal-stretcher", Lang::Nl), "Metselwerk 100 220×62.5 halfsteensverband");
        assert_eq!(name("system.masonry-waal-stack", Lang::En), "Brickwork 100 220×62.5 stack bond");
        assert_eq!(name("system.masonry-dik-stretcher", Lang::De), "Mauerwerk 100 220×75 Läuferverband");
        assert_eq!(name("system.cladding-timber-boards-140", Lang::En), "Timber cladding 18 4000×140 staggered");
        assert_eq!(name("system.hollow-core-260", Lang::Nl), "Kanaalplaat 260 1200×6000");
        assert_eq!(name("system.cladding-zinc-standing-seam-430", Lang::Fr), "Zinc 0,8 430×6000");
    }

    #[test]
    fn a_timber_frame_has_its_layers_against_one_another() {
        let t = starter().into_iter().find(|t| t.id == "system.timber-frame-140").unwrap();
        assert_eq!(t.members.framing, Some(Framing::PLATES.with_unit(3.3)));
        // from the outside in: the membrane, the frame, plywood, the vapour control layer, the
        // service zone, gypsum board; each layer against the one before it
        let mut faces: Vec<(f64, f64, &str)> = t.faces().map(|(offset, _, m, p)| (offset, m.map_or(0.0, |m| m.depth).max(p.thickness), p.material.as_str())).collect();
        faces.sort_by(|a, b| b.0.total_cmp(&a.0));
        let materials: Vec<&str> = faces.iter().map(|f| f.2).collect();
        assert_eq!(materials, ["breather-membrane", "mineral-wool", "plywood", "vapour-control-membrane", "mineral-wool", "gypsum-board"]);
        for pair in faces.windows(2) {
            let (a, b) = (pair[0], pair[1]);
            assert!(((a.0 - a.1 / 2.0) - (b.0 + b.1 / 2.0)).abs() < 1e-12, "{} against {}", b.2, a.2);
        }
        let (interior, exterior) = t.extent();
        assert!((exterior - (0.07 + 0.0005)).abs() < 1e-12 && (interior + (0.07 + 0.018 + 0.0002 + 0.045 + 0.0125)).abs() < 1e-12, "{interior} {exterior}");
        // the boards are two bays wide and as high as the frame's rows; the battens framed
        for l in &t.layers {
            match &l.members {
                Some(m) => assert_eq!((m.framing, l.grid.bay), (Some(Framing::PLATES.with_header(m.width)), t.grid.bay), "a batten over an opening"),
                None if l.panels.material.ends_with("membrane") => assert_eq!((l.grid.bay, l.grid.row), (50.0, 1.5)),
                None => assert_eq!((l.grid.bay, l.grid.row), (2.0 * t.grid.bay, t.grid.row)),
            }
        }
        let wide = starter().into_iter().find(|t| t.id == "system.timber-frame-184-610").unwrap();
        assert_eq!((wide.grid.bay, wide.grid.row, wide.layers[1].grid.bay), (0.61, 2.44, 1.22));
    }

    #[test]
    fn the_layers_of_a_type_are_laid_against_one_another() {
        // every starter type's layers lie against one another already
        for t in starter() {
            assert!(t.closed_up(), "{}", t.id);
        }
        let frame = starter().into_iter().find(|t| t.id == "system.timber-frame-140").unwrap();
        let material = |t: &SystemType, part: Option<usize>| part.map_or("the frame", |k| t.layers[k].panels.material.as_str()).to_string();
        let across = |t: &SystemType| -> Vec<String> { t.sequence().into_iter().map(|part| material(t, part)).collect() };
        assert_eq!(across(&frame), ["breather-membrane", "the frame", "plywood", "vapour-control-membrane", "mineral-wool", "gypsum-board"]);
        assert_eq!(frame.sides(), (vec![0], vec![1, 2, 3, 4]));
        // a layer pulled away leaves room; closing up lays it back, to the tenth of a micron
        let mut t = frame.clone();
        t.layers[4].offset -= 0.03;
        assert!(!t.closed_up());
        t.close_up();
        assert!(t.closed_up() && (t.layers[4].offset - frame.layers[4].offset).abs() < 1e-12);
        // the plywood (18) moved out past the frame (140) lies against its exterior face, under
        // the membrane (0.5), and the layers inside move up to the frame
        let mut t = frame.clone();
        assert!(t.shift(1, true));
        assert_eq!(across(&t), ["breather-membrane", "plywood", "the frame", "vapour-control-membrane", "mineral-wool", "gypsum-board"]);
        let near = |a: f64, b: f64| (a - b).abs() < 1e-12;
        assert!(near(t.layers[1].offset, 0.07 + 0.009) && near(t.layers[0].offset, 0.07 + 0.018 + 0.00025) && near(t.layers[2].offset, -(0.07 + 0.0001)), "{:?}", t.layers.iter().map(|l| l.offset).collect::<Vec<_>>());
        assert!(t.closed_up());
        // and back in; the outermost goes no further out, the innermost no further in
        assert!(t.shift(1, false));
        assert_eq!(across(&t), across(&frame));
        assert!(!t.shift(0, true) && !t.shift(4, false) && !t.shift(9, true));
        // a layer more lies against the outermost of its side and is like it
        let gypsum = t.add_layer(false);
        assert_eq!((gypsum, &t.layers[5].panels, t.sequence().last().copied()), (5, &Panels::new("gypsum-board", 0.0125), Some(Some(5))));
        assert!(near(t.layers[5].offset, t.layers[4].offset - 0.0125) && t.closed_up());
        // a type without layers: boards like its panels, against its deepest part (150 / 2)
        let mut curtain = starter().into_iter().next().unwrap();
        let k = curtain.add_layer(true);
        assert_eq!((curtain.layers[k].grid, curtain.layers[k].members.clone(), curtain.layers[k].panels.clone()), (curtain.grid, None, curtain.panels.clone()));
        assert!(near(curtain.layers[k].offset, 0.075 + 0.012) && curtain.closed_up());
        assert_eq!(curtain.check(&materials()), Ok(()));
    }

    #[test]
    fn a_type_that_does_not_make_a_system_is_refused() {
        let good = starter().into_iter().next().unwrap();
        let with = |f: &dyn Fn(&mut SystemType)| {
            let mut t = good.clone();
            f(&mut t);
            t.check(&materials())
        };
        assert_eq!(with(&|t| t.grid.bay = 0.04), Err(LibraryError::BadGrid), "a bay narrower than the members");
        assert_eq!(with(&|t| t.grid.row = 0.0), Err(LibraryError::BadGrid));
        assert_eq!(with(&|t| t.members.depth = 0.0), Err(LibraryError::NotPositive));
        assert_eq!(with(&|t| t.members.framing = Some(Framing::PLATES.with_header(0.0))), Err(LibraryError::NotPositive), "a header of nothing");
        assert_eq!(with(&|t| t.panels.thickness = f64::NAN), Err(LibraryError::NotPositive));
        assert_eq!(with(&|t| t.members.material = "unobtainium".into()), Err(LibraryError::UnknownMaterial("unobtainium".into())));
        assert_eq!(with(&|t| t.id = " ".into()), Err(LibraryError::NoKey));
    }

    #[test]
    fn a_type_reads_back_from_json_and_leaves_out_what_it_lacks() {
        for t in starter() {
            let text = serde_json::to_string(&t).unwrap();
            assert_eq!(serde_json::from_str::<SystemType>(&text).unwrap(), t);
        }
        let curtain = serde_json::to_value(&starter()[0]).unwrap();
        assert!(curtain.get("layers").is_none() && curtain.get("lying").is_none() && curtain.get("corners").is_none() && curtain["grid"].get("pattern").is_none(), "{curtain}");
        let aluminium = starter().into_iter().find(|t| t.id == "system.frame-aluminium-75").unwrap();
        assert_eq!(serde_json::to_value(&aluminium).unwrap()["corners"], "mitre");
        assert!(serde_json::to_value(&aluminium).unwrap()["members"].get("framing").is_none());
        let frame = serde_json::to_value(starter().into_iter().find(|t| t.id == "system.timber-frame-140").unwrap()).unwrap();
        assert_eq!(frame["members"]["framing"], serde_json::json!({"bottom_plates": 1, "top_plates": 1, "header": 0.2, "unit": 3.3}));
        // a framing written without a header has the nominal one
        let read: Framing = serde_json::from_str(r#"{"bottom_plates": 1, "top_plates": 2}"#).unwrap();
        assert_eq!(read, Framing { top_plates: 2, ..Framing::PLATES });
    }
}
